// Ref: #/components/schemas/MediaKind
type MediaKind string

const (
	MediaKindMovies MediaKind = "movies"
	MediaKindSeries MediaKind = "series"
	MediaKindMusic  MediaKind = "music"
)

// AllValues returns all MediaKind values.
func (MediaKind) AllValues() []MediaKind {
	return []MediaKind{
		MediaKindMovies,
		MediaKindSeries,
		MediaKindMusic,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s MediaKind) MarshalText() ([]byte, error) {
	switch s {
	case MediaKindMovies:
		return []byte(s), nil
	case MediaKindSeries:
		return []byte(s), nil
	case MediaKindMusic:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *MediaKind) UnmarshalText(data []byte) error {
	switch MediaKind(data) {
	case MediaKindMovies:
		*s = MediaKindMovies
		return nil
	case MediaKindSeries:
		*s = MediaKindSeries
		return nil
	case MediaKindMusic:
		*s = MediaKindMusic
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

